using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using PhoViet;
public static class ConfigureThunderstorm{public static object Main(){if(Application.isPlaying)throw new Exception("Edit required");var g=UnityEngine.Object.FindAnyObjectByType<PhoVietGame>();var shader=Shader.Find("PhoViet/Thunderstorm FX");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new Exception("FX shader not ready");if(!AssetDatabase.IsValidFolder("Assets/PhoViet/Art/Weather"))AssetDatabase.CreateFolder("Assets/PhoViet/Art","Weather");Material Create(string name,int mode,Color color,bool additive){string p="Assets/PhoViet/Art/Weather/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){m=new Material(shader);AssetDatabase.CreateAsset(m,p);}m.SetFloat("_Mode",mode);m.SetColor("_Color",color);m.SetFloat("_DstBlend",additive?1:10);EditorUtility.SetDirty(m);return m;}g.stormRainMaterial=Create("PV_StormRain",0,new Color(.8f,.9f,1,.8f),false);g.stormBoltMaterial=Create("PV_Lightning",1,Color.white,true);g.stormWarningMaterial=Create("PV_LightningWarning",2,Color.white,true);g.stormFireTemplate=g.vehicles.First(v=>v.crashEffect!=null).crashEffect;g.thunderstormEnabled=true;EditorUtility.SetDirty(g);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(g.gameObject.scene);EditorSceneManager.SaveScene(g.gameObject.scene);var result=new{success=true,materials=3,template=g.stormFireTemplate.name,shaderErrors=ShaderUtil.ShaderHasError(shader)};File.WriteAllText("Captures/storm-configure.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
